#!/usr/bin/env python3
"""Generate include/computer/Cp437Font.h from the raw VGA8.F16 bitmap.

VGA8.F16 is the IBM VGA 8x16 text-mode ROM font in the BIOS's native raw format:
256 glyphs, each 16 bytes (one byte per scanline, bit 7 = leftmost pixel). The
raw bitmap of a hardware ROM font is public domain (US copyright does not protect
bitmap font data); this dump comes from VileR's vga-text-mode-fonts collection
(int10h.org), acknowledged in the README. See README.md here for provenance.

Run from the repo root:  python3 vendor/cp437font/make_font.py
"""
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
SRC = os.path.join(HERE, "VGA8.F16")
OUT = os.path.normpath(os.path.join(HERE, "..", "..", "include", "computer", "Cp437Font.h"))

GLYPHS = 256
ROWS = 16


def main():
    with open(SRC, "rb") as f:
        data = f.read()
    if len(data) != GLYPHS * ROWS:
        sys.exit(f"error: {SRC} is {len(data)} bytes, expected {GLYPHS * ROWS}")

    lines = []
    lines.append("// Cp437Font.h - GENERATED by vendor/cp437font/make_font.py; do not edit.")
    lines.append("// IBM VGA 8x16 CP437 character ROM: 256 glyphs x 16 scanlines, one byte")
    lines.append("// per scanline (bit 7 = leftmost pixel). Public-domain bitmap; see")
    lines.append("// vendor/cp437font/README.md for provenance.")
    lines.append("#ifndef CP437FONT_H")
    lines.append("#define CP437FONT_H")
    lines.append("")
    lines.append("#include <cstdint>")
    lines.append("")
    lines.append("namespace Computer")
    lines.append("{")
    lines.append(f"    // [glyph * 16 + scanline] -> 8 pixels. {GLYPHS} glyphs.")
    lines.append(f"    static const uint8_t kCp437Font[{GLYPHS} * {ROWS}] = {{")
    for g in range(GLYPHS):
        row = data[g * ROWS:(g + 1) * ROWS]
        vals = ", ".join(f"0x{b:02X}" for b in row)
        lines.append(f"        {vals}, // 0x{g:02X}")
    lines.append("    };")
    lines.append("} // namespace Computer")
    lines.append("")
    lines.append("#endif // CP437FONT_H")

    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    with open(OUT, "w") as f:
        f.write("\n".join(lines) + "\n")
    print(f"wrote {OUT} ({GLYPHS} glyphs)")


if __name__ == "__main__":
    main()
